solution:
function subsets(nums) {
  const result = [];
  const current = [];

  function explore(start) {
    result.push([...current]);             // every node of the tree is a subset: save a COPY
    for (let i = start; i < nums.length; i++) {
      current.push(nums[i]);               // choose
      explore(i + 1);                      // explore (only later numbers, so no duplicates)
      current.pop();                       // un-choose
    }
  }

  explore(0);
  return result;
}

